<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/constants.php'; require_once __DIR__.'/../includes/auth.php'; requireRole(ROLE_ADMIN);
$db=Database::getConnection(); $adminId=(int)currentUserId(); $message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
requireCsrfToken(); $id=(int)($_POST['incident_id']??0); $review=$_POST['review_status']??''; $violation=$_POST['violation_status']??''; $remarks=trim((string)($_POST['admin_remarks']??'')); $vtype=trim((string)($_POST['violation_type']??''));
 $allowedR=['Pending Review','Reviewed','Resolved']; $allowedV=['No Violation','For Review','Verified Violation'];
 if($id>0 && in_array($review,$allowedR,true) && in_array($violation,$allowedV,true)){
  $st=$db->prepare("UPDATE delivery_incident SET review_status=?,violation_status=?,violation_type=?,admin_remarks=?,reviewed_by=?,reviewed_at=NOW(),resolved_at=CASE WHEN ?='Resolved' THEN COALESCE(resolved_at,NOW()) ELSE resolved_at END WHERE incident_id=?");
  $st->execute([$review,$violation,$vtype?:null,$remarks?:null,$adminId,$review,$id]); $message='Incident review saved.';
 }
}
$filter=$_GET['status']??''; $sql="SELECT di.*,o.order_number,d.full_name AS driver_name,t.plate_number,su.full_name AS reviewer FROM delivery_incident di JOIN `order` o ON o.order_id=di.order_id JOIN driver d ON d.driver_id=di.driver_id LEFT JOIN truck t ON t.truck_id=di.truck_id LEFT JOIN system_user su ON su.user_id=di.reviewed_by"; $args=[];
if(in_array($filter,['Pending Review','Reviewed','Resolved'],true)){ $sql.=" WHERE di.review_status=?";$args[]=$filter; } $sql.=" ORDER BY di.reported_at DESC,di.incident_id DESC"; $st=$db->prepare($sql);$st->execute($args);$rows=$st->fetchAll(PDO::FETCH_ASSOC);
require_once __DIR__.'/../includes/header.php';
?>
<style>.page{max-width:1400px;margin:25px auto;padding:0 18px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.toolbar a{padding:8px 12px;border:1px solid var(--color-border,#ddd);border-radius:8px;text-decoration:none}.inc{background:var(--color-surface,#fff);border:1px solid var(--color-border,#ddd);border-radius:12px;padding:18px;margin:12px 0}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.review{display:grid;grid-template-columns:1fr 1fr 1fr 2fr auto;gap:8px;margin-top:14px}.review select,.review input{padding:9px;border:1px solid var(--color-border,#ccc);border-radius:7px;background:var(--color-surface,#fff);color:var(--color-text-primary,#111)}.review button{padding:9px 14px;border:0;border-radius:7px;background:var(--color-primary,#2563eb);color:#fff}.badge{font-weight:700}@media(max-width:900px){.meta,.review{grid-template-columns:1fr}}</style>
<div class="page"><h1>Delivery Incidents</h1><p>Review reported delivery delays and determine whether they are valid operational/external incidents or verified driver violations.</p><?php if($message):?><p><strong><?=htmlspecialchars($message)?></strong></p><?php endif;?><div class="toolbar"><a href="?">All</a><a href="?status=Pending+Review">Pending Review</a><a href="?status=Reviewed">Reviewed</a><a href="?status=Resolved">Resolved</a></div>
<?php if(!$rows):?><div class="inc">No incident reports found.</div><?php endif;?><?php foreach($rows as $r):?><div class="inc"><div class="meta"><div><small>Order</small><br><strong><?=htmlspecialchars($r['order_number'])?></strong></div><div><small>Driver</small><br><?=htmlspecialchars($r['driver_name'])?></div><div><small>Truck</small><br><?=htmlspecialchars($r['plate_number']??'—')?></div><div><small>Reported</small><br><?=htmlspecialchars($r['reported_at'])?></div></div><h3><?=htmlspecialchars($r['incident_type'])?> <span class="badge">(<?=htmlspecialchars($r['incident_category'])?>)</span></h3><p><?=nl2br(htmlspecialchars($r['description']))?></p><p><strong>Estimated delay:</strong> <?=number_format((int)$r['estimated_delay_minutes'])?> minutes &nbsp; <strong>Violation:</strong> <?=htmlspecialchars($r['violation_status'])?> &nbsp; <strong>Review:</strong> <?=htmlspecialchars($r['review_status'])?></p><?php if($r['evidence_path']):?><p><a href="<?=BASE_URL.htmlspecialchars($r['evidence_path'])?>" target="_blank">View evidence</a></p><?php endif;?><form method="post" class="review"><?=csrfField()?><input type="hidden" name="incident_id" value="<?=(int)$r['incident_id']?>"><select name="review_status"><?php foreach(['Pending Review','Reviewed','Resolved'] as $v):?><option <?=$r['review_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><select name="violation_status"><?php foreach(['No Violation','For Review','Verified Violation'] as $v):?><option <?=$r['violation_status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><input name="violation_type" value="<?=htmlspecialchars($r['violation_type']??'')?>" placeholder="Violation type (if any)"><input name="admin_remarks" value="<?=htmlspecialchars($r['admin_remarks']??'')?>" placeholder="Admin remarks"><button>Save Review</button></form></div><?php endforeach;?></div>
